import{_ as a,c as i,o,a2 as t}from"./chunks/framework.bjzS3PU6.js";const d=JSON.parse('{"title":"Conspirazorg","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/Conspirazorg.md","filePath":"entries/people/Conspirazorg.md"}'),r={name:"entries/people/Conspirazorg.md"};function n(s,e,l,c,p,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="conspirazorg" tabindex="-1">Conspirazorg <a class="header-anchor" href="#conspirazorg" aria-label="Permalink to &quot;Conspirazorg&quot;">​</a></h1><hr><p><strong>OCCUPATION</strong>: Conspiracy Theorist, Media Personality<br><strong>KNOWN FOR</strong>: SnarkCast guest appearances<br><strong>SPECIALTY</strong>: Government conspiracy theories, Miter Corporation research</p><hr><p><strong>Conspirazorg</strong> is an American conspiracy theorist and media personality. He is best known for guest appearances on <em>SnarkCast</em>, a satirical podcast, where he presents theories about covert government operations and corporate misconduct.</p><p><strong>At a glance</strong></p><ul><li>Guest commentator on <em>SnarkCast</em> satirical podcast</li><li>Specializes in government conspiracy theories and covert research programs</li><li>Known for animated, energetic presentation style</li><li>Publicized allegations about <a href="./../organizations/Miter-Corporation">Miter Corporation</a> experiments on children</li><li>Identified <a href="./../subjects/G-BOY">G*BOY</a> as escaped facility subject who became online symbol</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Conspirazorg appears as a guest on <em>SnarkCast</em>, where he presents conspiracy theories with animated, urgent delivery. His commentary focuses on alleged covert government operations, unethical corporate research programs, and institutional coverups. He is known for rapid, passionate explanations while directing technical producers to display supporting documentation.</p><h2 id="snarkcast-appearances" tabindex="-1">SnarkCast Appearances <a class="header-anchor" href="#snarkcast-appearances" aria-label="Permalink to &quot;SnarkCast Appearances&quot;">​</a></h2><h3 id="november-2025-appearance" tabindex="-1">November 2025 Appearance <a class="header-anchor" href="#november-2025-appearance" aria-label="Permalink to &quot;November 2025 Appearance&quot;">​</a></h3><p>In November 2025, Conspirazorg appeared on <em>SnarkCast</em> with host <a href="./Milton-Plumb">Milton Plumb</a> to discuss his theories about <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>. His presentation challenged Plumb&#39;s initial assessment that facility activities were &quot;random experiments.&quot;</p><p>Conspirazorg argued this interpretation was intentional misdirection, stating the truth was &quot;much darker&quot; and &quot;more insidious.&quot; He directed the show&#39;s technical producer, Jimmy, to display files about St. Juniper Secure Lab.</p><h2 id="miter-corporation-allegations" tabindex="-1">Miter Corporation Allegations <a class="header-anchor" href="#miter-corporation-allegations" aria-label="Permalink to &quot;Miter Corporation Allegations&quot;">​</a></h2><p>Conspirazorg identified the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper facility</a> as operated by <a href="./../organizations/Miter-Corporation">Miter Corporation</a>, a government contractor. While Plumb acknowledged existing conspiracy theories about &quot;psionic human testing&quot; and &quot;super psychic soldiers,&quot; Conspirazorg provided more detailed allegations:</p><ul><li>Kidnapping of &quot;homeless babies&quot; as experimental subjects</li><li>Traumatic experiments involving gravity manipulation and sensory deprivation</li><li>Distribution of &quot;animal badges&quot; to child subjects for psychological manipulation</li><li>Goal of unlocking &quot;latent occult, psychic nature&quot; for military weapons development</li><li>Sale of psychic capabilities to be used &quot;against our adversaries&quot;</li></ul><p>Conspirazorg claimed that official narratives about a facility &quot;malfunction&quot; were false. According to his theory, one experimental subject &quot;freaked out&quot; and &quot;blew the doors off the whole thing,&quot; escaping the facility.</p><h2 id="g-boy-identification" tabindex="-1">G*BOY Identification <a class="header-anchor" href="#g-boy-identification" aria-label="Permalink to &quot;G*BOY Identification&quot;">​</a></h2><p>Conspirazorg directed the show&#39;s producer to display footage of &quot;the Fox kid&quot; being &quot;chased through St. Juniper.&quot; He identified this figure as <a href="./../subjects/G-BOY">G*BOY</a>, the escaped facility subject.</p><p>He noted that G*BOY &quot;has blown up online&quot; and is &quot;becoming some sort of symbol,&quot; representing his awareness of the figure&#39;s viral cultural presence and symbolic significance beyond the alleged escape incident.</p><h2 id="public-profile" tabindex="-1">Public Profile <a class="header-anchor" href="#public-profile" aria-label="Permalink to &quot;Public Profile&quot;">​</a></h2><p>Conspirazorg&#39;s presentation style is characterized by:</p><ul><li>Animated, energetic delivery with varying vocal pitch for emphasis</li><li>Rapid speech when excited about evidence or connections</li><li>Use of colloquial language and profanity for emphasis</li><li>Direction of technical staff to display supporting documentation</li><li>Building of dramatic tension while presenting theories</li><li>Urgent, conversational tone typical of conspiracy content creators</li></ul><p>His theories about Miter Corporation and Saint Juniper operations align substantially with information later recovered by activist researchers, though his public platform and theatrical presentation style differ from the more careful documentation approaches used by groups like <a href="./../organizations/The-Bloc">The Bloc</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Milton-Plumb">Milton Plumb</a></li><li><a href="./Rectford-Shillman">Rectford Shillman</a></li><li><a href="./../organizations/SnarkCast">SnarkCast</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./../subjects/G-BOY">G*BOY</a></li><li><a href="./../organizations/The-Bloc">The Bloc</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><strong>SnarkCast episode</strong> — Featuring Conspirazorg (November 12, 2025) <ul><li>Satirical podcast discussing Miter Corporation and G*BOY theories</li></ul></li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',30)])])}const m=a(r,[["render",n]]);export{d as __pageData,m as default};
